/**
 * @file motor.h
 * @brief DC motor driver for 2 x BTN8982TA half-bridge, sign-magnitude PWM
 *   V > 0 : half-bridge A = PWM, half-bridge B = low
 *   V < 0 : half-bridge A = low, half-bridge B = PWM
 * Average motor voltage = duty * Vbus. Dead time is generated by the BTN8982.
 * The ADC trigger (current sense) is moved to the middle of the on-time,
 * where the high-side MOSFET of the active half-bridge conducts.
 *
 */

#ifndef MOTOR_H
#define MOTOR_H

#include <stdbool.h>
#include <stdint.h>

typedef enum { MOTOR_HALF_A = 0, MOTOR_HALF_B = 1 } motor_half_t;

typedef struct {
    float        vbus;    // supply voltage [V]
    int8_t       dir;     // wiring direction +1/-1
    uint16_t     period;  // PWM period [timer counts]
    bool         enabled; // bridge enabled (INH high)
    float        v_cmd;   // last commanded voltage (model sign) [V]
    float        duty;    //[duty] 0..1
    motor_half_t active;  // half-bridge currently switching
} motor_t;

void motor_init(motor_t *m, float vbus, int8_t dir);
// Enable/disable the bridge. Disabling also forces 0 V
void motor_enable(motor_t *m, bool enable);
// Command a voltage in the MODEL sign convention (+V -> +dtheta). Ignored while disabled
void         motor_set_voltage(motor_t *m, float volts);
float        motor_voltage(const motor_t *m);
float        motor_duty(const motor_t *m);
motor_half_t motor_active_half(const motor_t *m);
bool         motor_is_enabled(const motor_t *m);

#endif